window.docContents[25].resolve({"/Storage-and-commands/Loops/#Core-C______--Storage-and-commands--Loops":{"contents":"The rule While-T recurs on its own conclusion. A return in the body interrupts the loop. The divergence of while (true) {} has no derivation, a limitation of inductive big step semantics (Leroy and Grall).\n\nThe for is defined through while. The variable of the initialiser has the loop as its scope, the body is a block of its own, and the step runs after the body, outside the body's scope.\n\n","context":"Core C++\u0009Storage and commands","header":"4.6. Loops","id":"/Storage-and-commands/Loops/#Core-C______--Storage-and-commands--Loops"}});